package com.fitpulse.model.entity;
import com.fitpulse.model.enums.ContentStatus; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="review_reports",uniqueConstraints=@UniqueConstraint(columnNames={"review_id","reporter_id"})) public class ReviewReport { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Review review; @ManyToOne(optional=false) @JoinColumn(name="reporter_id") private User reporter; @Column(nullable=false,length=500) private String reason; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ContentStatus status=ContentStatus.OPEN; @Column(nullable=false) private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Review getReview(){return review;} public void setReview(Review v){review=v;} public User getReporter(){return reporter;} public void setReporter(User v){reporter=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;} }
